const getVendasResumo = `-- name: GetVendasResumo :one
SELECT
    COALESCE(SUM(valor_total), 0) AS total_vendas,
    COUNT(*) AS total_pedidos,
    CASE WHEN COUNT(*) > 0 THEN COALESCE(SUM(valor_total), 0) / COUNT(*) ELSE 0 END AS ticket_medio,
    COALESCE(SUM(valor_desconto), 0) AS total_descontos
FROM pedidos_canonicos
WHERE empresa_id = $1
  AND deleted_at IS NULL
  AND ($2::uuid IS NULL OR loja_id = $2)
  AND ($3::timestamptz IS NULL OR data_hora >= $3)
  AND ($4::timestamptz IS NULL OR data_hora <= $4)
  AND status != 'cancelado'
`

type GetVendasResumoParams struct {
	EmpresaID uuid.UUID `json:"empresa_id"`
	Column2   uuid.UUID `json:"column_2"`
	Column3   time.Time `json:"column_3"`
	Column4   time.Time `json:"column_4"`
}

type GetVendasResumoRow struct {
	TotalVendas    interface{} `json:"total_vendas"`
	TotalPedidos   int64       `json:"total_pedidos"`
	TicketMedio    int32       `json:"ticket_medio"`
	TotalDescontos interface{} `json:"total_descontos"`
}

// Resumo de Vendas
func (q *Queries) GetVendasResumo(ctx context.Context, arg GetVendasResumoParams) (GetVendasResumoRow, error) {
	row := q.db.QueryRow(ctx, getVendasResumo,
		arg.EmpresaID,
		arg.Column2,
		arg.Column3,
		arg.Column4,
	)
	var i GetVendasResumoRow
	err := row.Scan(
		&i.TotalVendas,
		&i.TotalPedidos,
		&i.TicketMedio,
		&i.TotalDescontos,
	)
	return i, err
}

